The Centrifuge router enables several features such as multicall actions, permissionlessly claiming, ERC20 wrapping and locking requests. In order to allow the router contract to perform certain actions to the vault, it must first be added as an endorsed operator. open() must be called to enable vault interactions and left as such to allow for permissionlessly claiming.
```solidity
function open(address vault) public protected {
    IERC7540Vault(vault).setEndorsedOperator(_initiator(), true);
}
```
However, there are some serious concerns with this because if a user has an approval for the vault, anyone can requestDeposit() on behalf of this owner and pass a controller parameter for which they control. There is no validation on the vault side because isOperator[owner][msg.sender] holds true as the caller is the router itself.
The same applies to requestRedeem(), allowing tranche tokens to be redeemed unwillingly in which the controller is any arbitrary account.
```solidity
function requestDeposit(address vault, uint256 amount, address controller, address owner, uint256 topUpAmount)
external
payable
protected
{
    (address asset,) = poolManager.getVaultAsset(vault);
    if (owner == address(this)) {
        _approveMax(asset, vault);
    }
    _pay(topUpAmount);
    IERC7540Vault(vault).requestDeposit(amount, controller, owner);
}
```

Metadata of tokenId can be partially configured. While projectId is empty string, the creator can change the token parameters anytime:
```solidity
function spawn(
    uint256 tokenId,
    string calldata name,
    string calldata symbol,
    string calldata projectId,
    IIPSeedCurve curve,
    bytes32 curveParameters,
    address sourcer
) public {
    if (tokenId != computeTokenId(_msgSender(), projectId)) {
        revert InvalidTokenId();
    }
    // ERC1155's `exists` function checks for totalSupply > 0, which is not what
    // we want here
    if (bytes(tokenMeta[tokenId].projectId).length > 0) {
        revert TokenAlreadyExists();
    }
    Metadata memory newMetadata =
        Metadata(sourcer, sourcer, name, symbol, projectId, curve, curveParameters);
    tokenMeta[tokenId] = newMetadata;
    emit Spawned(tokenId, sourcer, newMetadata);
}
```
This behavior introduces following attack:
1. Attacker configures only Curve address for certain tokenId.
2. Attacker mints arbitrary amount of that tokenId because Curve parameters are 0, hence price is 0.
3. Attacker configures again that tokenId, but now with real values.
4. Attacker sells all minted tokens, draining whole balance of IPSeed.
Here is link to PoC:
https://gist.github.com/T1MOH593/4c28ede6cdc6d183927bb7e14352ea73

Currently user can specify arbitrary implementation of IIPSeedCurve:
```solidity
function spawn(
    uint256 tokenId,
    string calldata name,
    string calldata symbol,
    string calldata projectId,
    IIPSeedCurve curve,
    bytes32 curveParameters,
    address sourcer
) public {
    Metadata memory newMetadata =
        Metadata(sourcer, sourcer, name, symbol, projectId, curve, curveParameters);
    tokenMeta[tokenId] = newMetadata;
    emit Spawned(tokenId, sourcer, newMetadata);
}
```
However Curve implementation can be malicious: for example return 0 price on buy and arbitrary price on sell. On burning and minting IPSeed quotes it from Curve implementation:
```solidity
function getBuyPrice(uint256 tokenId, uint256 want)
    public
    returns (uint256 gross, uint256 net, uint256 protocolFee, uint256 sourcerFee)
{
    net = tokenMeta[tokenId].priceCurve.getBuyPrice(
        totalSupply(tokenId), want, tokenMeta[tokenId].curveParameters
    );
    (protocolFee, sourcerFee) = computeFees(net);
    gross = net + protocolFee + sourcerFee;
}

function getSellPrice(uint256 tokenId, uint256 sell)
    public
    returns (uint256 gross, uint256 net, uint256 protocolFee, uint256 sourcerFee)
{
    gross = tokenMeta[tokenId].priceCurve.getSellPrice(
        totalSupply(tokenId), sell, tokenMeta[tokenId].curveParameters
    );
    (protocolFee, sourcerFee) = computeFees(gross);
    net = gross - protocolFee - sourcerFee;
}
```
Malicious Curve implementation can incorrectly price tokens and therefore drain ETH on selling.

SegmentedSegmentTree464.update needs to perform an overflow check in case the new value is greater than the old value. This overflow check is done when adding the new difference to each node in each layer (using addClean). Furthermore, there's a final overflow check by adding up all nodes in the first layer in total(core).
However, in total, the nodes in individual groups are added using DirtyUint64.sumPackedUnsafe:
```solidity
function total(Core storage core) internal view returns (uint64) {
    return DirtyUint64.sumPackedUnsafe(core.layers[0][0], 0, _C)
        + DirtyUint64.sumPackedUnsafe(core.layers[0][1], 0, _C);
}
```
The nodes in a group can overflow without triggering an overflow & revert. The impact is that the order book depth and claim functionalities break for all users.
```solidity
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;
import "forge-std/Test.sol";
import "forge-std/StdJson.sol";
import "../../contracts/mocks/SegmentedSegmentTree464Wrapper.sol";
contract SegmentedSegmentTree464Test is Test {
    using stdJson for string;
    uint32 private constant _MAX_ORDER = 2**15;
    SegmentedSegmentTree464Wrapper testWrapper;
    function setUp() public {
        testWrapper = new SegmentedSegmentTree464Wrapper();
    }
    function testTotalOverflow() public {
        uint64 half64 = type(uint64).max / 2 + 1;
        testWrapper.update(0, half64);
        // map to the right node of layer 0, group 0
        testWrapper.update(_MAX_ORDER / 2 - 1, half64);
        assertEq(testWrapper.total(), 0);
    }
}
```

The order queue is implemented as a ring buffer, to get an order (Orderbook.getOrder) the index in the queue is computed as orderIndex % _MAX_ORDER. The owner of an OrderNFT also uses this function.
```solidity
function _getOrder(OrderKey calldata orderKey) internal view returns (Order storage) {
    return _getQueue(orderKey.isBid, orderKey.priceIndex).orders[orderKey.orderIndex & _MAX_ORDER_M];
}
CloberOrderBook(market).getOrder(decodeId(tokenId)).owner
```
Therefore, the current owner of the NFT of orderIndex also owns all NFTs with orderIndex + k * _MAX_ORDER. An attacker can set approvals of future token IDs to themself. These approvals are not cleared on OrderNFT.onMint when a victim mints this future token ID, allowing the attacker to steal the NFT and cancel the NFT to claim their tokens.
