function _startGradualWeightChange(uint256 startTime, uint256 endTime, ... ) ... {
...
_setMiscData(
_getMiscData().insertUint32(startTime, _START_TIME_OFFSET).insertUint32(endTime, _END_TIME_OFFSET)
,!);
// this convert the values to 32 bits
...
